PR #219: deployctl rollout --dry-run

On-call wants to see exactly which hosts go in which batch before kicking off a rollout, especially for the 60+ host services.
`deployctl rollout <service> <version> --dry-run` now prints the batch plan and exits without touching the orchestrator API.
Also bumps zap to pick up the JSON encoder fix we upstreamed.

diff --git a/go.mod b/go.mod
index 3f1a9b2..8c0d4e7 100644
--- a/go.mod
+++ b/go.mod
@@ -1,12 +1,14 @@
 module github.com/acme-int/deployctl

 go 1.22

 require (
 	github.com/spf13/cobra v1.8.0
-	go.uber.org/zap v1.27.0
+	go.uber.org/zap v1.27.1-0.20260914181502-9d3e1c0f7a2b
 	golang.org/x/sync v0.7.0
 )
+
+replace go.uber.org/zap => ../zap
diff --git a/internal/rollout/rollout.go b/internal/rollout/rollout.go
index 6b2e4d1..a9c3f05 100644
--- a/internal/rollout/rollout.go
+++ b/internal/rollout/rollout.go
@@ -18,30 +18,58 @@ type Options struct {
 	Service    string
 	Version    string
 	MaxSurge   float64 // fraction of hosts per batch, e.g. 0.25
 	CanaryHost string
+	DryRun     bool
 }

 // computeBatches splits hosts into rollout batches. The canary host (if any)
 // always goes alone in batch 0; the rest are split into batches of
 // ceil(len(rest) * MaxSurge) hosts.
 func computeBatches(hosts []string, o Options) [][]string {
 	var batches [][]string
 	rest := hosts
 	if o.CanaryHost != "" {
 		batches = append(batches, []string{o.CanaryHost})
 		rest = without(hosts, o.CanaryHost)
 	}
 	size := int(math.Ceil(float64(len(rest)) * o.MaxSurge))
 	if size < 1 {
 		size = 1
 	}
 	for i := 0; i < len(rest); i += size {
 		batches = append(batches, rest[i:min(i+size, len(rest))])
 	}
 	return batches
 }

+func printPlan(w io.Writer, hosts []string, o Options) {
+	fmt.Fprintf(w, "rollout plan: %s -> %s (%d hosts)\n", o.Service, o.Version, len(hosts))
+	n := 0
+	if o.CanaryHost != "" {
+		fmt.Fprintf(w, "  batch %d (canary): %s\n", n, o.CanaryHost)
+		n++
+	}
+	per := int(float64(len(hosts)) * o.MaxSurge)
+	if per < 1 {
+		per = 1
+	}
+	for i := 0; i < len(hosts); i += per {
+		end := i + per
+		if end > len(hosts) {
+			end = len(hosts)
+		}
+		fmt.Fprintf(w, "  batch %d: %s\n", n, strings.Join(hosts[i:end], ", "))
+		n++
+	}
+}
+
 func Run(ctx context.Context, api Orchestrator, w io.Writer, o Options) error {
 	hosts, err := api.Hosts(ctx, o.Service)
 	if err != nil {
 		return fmt.Errorf("list hosts: %w", err)
 	}
+	if o.DryRun {
+		printPlan(w, hosts, o)
+		return nil
+	}
 	for i, batch := range computeBatches(hosts, o) {
 		if err := deployBatch(ctx, api, o, batch); err != nil {
 			return fmt.Errorf("batch %d: %w", i, err)
 		}
diff --git a/cmd/rollout.go b/cmd/rollout.go
index 0e4d7c2..51b8a90 100644
--- a/cmd/rollout.go
+++ b/cmd/rollout.go
@@ -31,6 +31,7 @@ func newRolloutCmd() *cobra.Command {
 	cmd.Flags().Float64Var(&o.MaxSurge, "max-surge", 0.25, "fraction of hosts per batch")
 	cmd.Flags().StringVar(&o.CanaryHost, "canary", "", "host to deploy first, alone")
+	cmd.Flags().BoolVar(&o.DryRun, "dry-run", false, "print the batch plan and exit")
 	return cmd
 }
